CREATE TABLE GeoNames ( Id_GeoNames_GeoNamesDatabase VARCHAR(15), Country_GeoNames_GeoNamesDatabase VARCHAR(300), County_GeoNames_GeoNamesDatabase VARCHAR(300), State_GeoNames_GeoNamesDatabase VARCHAR(300), City_GeoNames_GeoNamesDatabase VARCHAR(300), Zip_GeoNames_GeoNamesDatabase VARCHAR(10), LatLong_GeoNames_GeoNamesDatabase VARCHAR(30), InsertDate_GeoNames_GeoNamesDatabase timestamp, PRIMARY KEY (Id_GeoNames_GeoNamesDatabase));
